// domain/ — pure Dart
class Order {
  final String id;
  final Money total;
  bool get isRefundable => total.amount > 0 && !isShipped;
}

abstract interface class OrderRepository {
  Future<Order> byId(String id);
}

// data/
class HttpOrderRepository implements OrderRepository {
  HttpOrderRepository(this._api);
  final ApiClient _api;

  @override
  Future<Order> byId(String id) async {
    final dto = await _api.getOrder(id); // OrderDto, snake_case
    return dto.toDomain();               // mapper at the boundary
  }
}

